class Solution {
public:
    int possibleStringCount(string word, int k) {
        const long long MOD = 1000000007;
        int n = word.size();
        long long P = 1;
        int g = 0;
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && word[j] == word[i]) j++;
            int r = j - i;
            g++;
            P = P * r % MOD;
            i = j;
        }
        if (g >= k) return (int)P;
        vector<long long> f(k, 0), nf(k, 0), pre(k + 1, 0);
        f[0] = 1;
        for (int i = 0; i < n; ) {
            int j = i;
            while (j < n && word[j] == word[i]) j++;
            int c = j - i;
            if (c > k) c = k;
            pre[0] = 0;
            for (int t = 0; t < k; t++) pre[t + 1] = (pre[t] + f[t]) % MOD;
            for (int t = 0; t < k; t++) {
                int lo = t - c;
                if (lo < 0) lo = 0;
                nf[t] = (pre[t] - pre[lo] + MOD) % MOD;
            }
            swap(f, nf);
            i = j;
        }
        long long bad = 0;
        for (int t = 0; t < k; t++) bad = (bad + f[t]) % MOD;
        return (int)((P - bad + MOD) % MOD);
    }
};
